import {MAZE,position,DIRECTIONS} from './engine.js';
export function render(canvas,game,reduced=false,viewport){const c=canvas.getContext('2d');if(!c)return;const dpr=viewport?.dpr||1,w=canvas.width/dpr,h=canvas.height/dpr,top=viewport?.top||0,bottom=viewport?.bottom||0,tx=w/19,ty=(h-top-bottom)/21,t=Math.min(tx,ty);c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.fillStyle='#000';c.fillRect(0,0,w,h);c.save();c.translate(0,top);
 MAZE.forEach((row,y)=>[...row].forEach((tile,x)=>{if(tile!=='#')return;c.fillStyle='#001452';c.fillRect(x*tx,y*ty,tx+.5,ty+.5);c.strokeStyle='#326cff';c.lineWidth=2.5;c.beginPath();if(MAZE[y-1]?.[x]!=='#'){c.moveTo(x*tx,y*ty+1);c.lineTo((x+1)*tx,y*ty+1);}if(MAZE[y+1]?.[x]!=='#'){c.moveTo(x*tx,(y+1)*ty-1);c.lineTo((x+1)*tx,(y+1)*ty-1);}if(row[x-1]!=='#'){c.moveTo(x*tx+1,y*ty);c.lineTo(x*tx+1,(y+1)*ty);}if(row[x+1]!=='#'){c.moveTo((x+1)*tx-1,y*ty);c.lineTo((x+1)*tx-1,(y+1)*ty);}c.stroke();}));
 for(const [key,type] of game.dots){const [x,y]=key.split(',').map(Number);c.beginPath();c.arc((x+.5)*tx,(y+.5)*ty,type==='o'?t*(reduced?.23:.22+.025*Math.sin(game.time*5)):Math.max(2,t*.085),0,Math.PI*2);c.fillStyle=type==='o'?'#ff00f5':'#fff';c.fill();}
 for(const ghost of game.ghosts){const p=position(ghost),x=(p.x+.5)*tx,y=(p.y+.5)*ty,r=t*.38;c.save();if(ghost.grace>0)c.globalAlpha=.55;c.fillStyle=game.power>0?(game.power<2&&Math.floor(game.time*8)%2?'#fff':'#147aff'):ghost.color;c.beginPath();c.arc(x,y,r,Math.PI,0);c.lineTo(x+r,y+r);for(let i=3;i>=0;i--)c.lineTo(x-r+i*r*2/3,y+r-(i%2?r*.22:0));c.closePath();c.fill();if(game.power>0){c.fillStyle='#fff';c.fillRect(x-r*.45,y-r*.13,r*.23,r*.23);c.fillRect(x+r*.2,y-r*.13,r*.23,r*.23);c.strokeStyle='#fff';c.lineWidth=1.5;c.beginPath();c.moveTo(x-r*.5,y+r*.45);for(let i=1;i<5;i++)c.lineTo(x-r*.5+i*r*.25,y+r*(i%2?.3:.45));c.stroke();}else{const d=DIRECTIONS[ghost.dir];for(const side of [-1,1]){const ex=x+side*r*.38,ey=y-r*.13;c.fillStyle='#fff';c.beginPath();c.ellipse(ex,ey,r*.28,r*.36,0,0,Math.PI*2);c.fill();c.fillStyle='#000';c.beginPath();c.arc(ex+d.x*r*.1,ey+d.y*r*.13,r*.14,0,Math.PI*2);c.fill();}}c.restore();}
 const p=position(game.player);c.save();if(game.immune>0&&Math.floor(game.time*10)%2)c.globalAlpha=.45;if(game.status==='hit')c.globalAlpha=.45;const angle={right:0,down:Math.PI/2,left:Math.PI,up:-Math.PI/2}[game.player.dir],mouth=reduced?.23:.18+Math.abs(Math.sin(game.time*13))*.32,x=(p.x+.5)*tx,y=(p.y+.5)*ty;c.fillStyle='#ffeb00';c.beginPath();c.moveTo(x,y);c.arc(x,y,t*.4,angle+mouth,angle+Math.PI*2-mouth);c.closePath();c.fill();c.restore();c.restore();
}
